/**
 * per-hour amounts by source; they sum to increaseRate (up to rounding)
 */
export type ProductionSources = {
    /**
     * flat output per hour, regardless of fields
     */
    base: number;
    /**
     * field output per hour after work rate and labour efficiency
     */
    fields: number;
    /**
     * from Agriculture / Lumbering / Masonry / Mining
     */
    tech: number;
    /**
     * from the mayor's politics
     */
    mayor: number;
    /**
     * from occupied valleys
     */
    valley: number;
    /**
     * from production items
     */
    buff: number;
    /**
     * troop food upkeep per game hour (negative; 0 for other resources), 2 decimals
     */
    upkeep: number;
    /**
     * (marchlands) output the tax rate sells to the merchant per game hour (negative), 2 decimals
     */
    tax: number;
    /**
     * bonus share from research
     */
    techBonus: number;
    /**
     * bonus share from the mayor's politics
     */
    mayorBonus: number;
    /**
     * bonus share from occupied valleys
     */
    valleyBonus: number;
    /**
     * bonus share from production items
     */
    buffBonus: number;
};

export type ResourceLine = {
    amount: number;
    max: number;
    storePercent: number;
    workRate: number;
    workPeople: number;
    /**
     * net change per game hour (food is after troop upkeep), 2 decimals
     */
    increaseRate: number;
    /**
     * production bonus as a share (0.25 = +25%)
     */
    bonus: number;
    breakdown: ProductionSources;
};

export type ResourceBean = {
    gold: number;
    /**
     * net gold per game hour, 2 decimals
     */
    goldRate: number;
    food: ResourceLine;
    wood: ResourceLine;
    stone: ResourceLine;
    iron: ResourceLine;
    /**
     * (marchlands) share of field output sold to the merchant as it is produced
     */
    taxRate: number;
    /**
     * gold per game hour: the base tax on population plus taxConverted
     */
    taxIncome: number;
    /**
     * (marchlands) gold per game hour the tax rate earns from field output
     */
    taxConverted: number;
    /**
     * gold per game hour the Gold Production item adds to the base tax (part of taxIncome)
     */
    taxItemBonus: number;
    /**
     * that item bonus, as a share of the base tax (0.25 = +25%)
     */
    taxItemShare: number;
    herosSalary: number;
    /**
     * troop food upkeep per game hour, 2 decimals
     */
    troopCostFood: number;
    curPopulation: number;
    maxPopulation: number;
    idlePopulation: number;
    workPeople: number;
    /**
     * labour efficiency as a share (1: every field fully staffed)
     */
    efficiency: number;
    populationDirection: number;
    /**
     * epoch milliseconds
     */
    updatedAt: number;
};

