export type AuthAccount = {
    id: number;
    username: string;
    email: string;
    isAdmin: boolean;
    createdAt: number;
    /**
     * null until the lord is created
     */
    player: {
        id: number;
        name: string;
    } | null;
};

export type ZoneStats = {
    /**
     * zone (state) id; the client names it
     */
    id: number;
    playerCount: number;
    castleCount: number;
    openFlats: number;
    /**
     * share of occupiable tiles that are taken (0-1)
     */
    settled: number;
};

/**
 * world fields are absent until the world has been seeded
 */
export type WorldInfo = {
    mapSize?: number;
    source?: 'generated' | 'legacy';
    seed?: string;
    /**
     * epoch milliseconds
     */
    createdAt?: number;
    /**
     * connected players
     */
    online: number;
};

export type ArmyPreset = {
    id: string;
    name: string;
    troops: {
        [key: string]: number;
    };
};

export type FlowAction = {
    type: 'setMayor';
    /**
     * attribute the new mayor is best at
     */
    stat: 'power' | 'management' | 'stratagem';
} | {
    type: 'trainTroops';
    /**
     * troop type id
     */
    troopId: number;
    /**
     * a number, or 'max' for as many as the city can afford
     */
    amount: 'max' | number;
} | {
    type: 'healTroops';
    /**
     * heal every injured troop, paid with resources or honor
     */
    payWith: 'resources' | 'honor';
    /**
     * 'armiesHome': once every army of the city is back (e.g. after farming)
     */
    when: 'now' | 'armiesHome';
} | {
    type: 'attackTargets';
    /**
     * saved army sent at each target
     */
    presetId: string;
    targets: {
        [key: string]: Array<number>;
    };
} | {
    type: 'wait';
    /**
     * 'time': a number of real minutes; 'armiesHome': until every army this run sent is back
     */
    until: 'time' | 'armiesHome';
    /**
     * real minutes (for until 'time'); not sped up by GAME_SPEED
     */
    minutes: number;
};

export type FlowSkippedCity = {
    cityId: number;
    cityName: string;
    reason: Message;
};

export type FlowRunLog = {
    /**
     * 1 for the first run of the flow, counting up
     */
    run: number;
    /**
     * epoch milliseconds
     */
    startedAt: number;
    /**
     * null while the run is still going
     */
    finishedAt: number | null;
    cities: Array<{
        cityId: number;
        cityName: string;
        /**
         * false: an action failed and everything the flow did in this city since the last wait was rolled back
         */
        ok: boolean;
        /**
         * the failure that rolled back this city's part of the run
         */
        error: Message | null;
        steps: Array<{
            action: Message;
            ok: boolean;
            /**
             * what happened, or why it failed
             */
            detail: Message;
            /**
             * the city could not do it right now (e.g. nothing affordable to train); the run carried on
             */
            skipped?: boolean;
            /**
             * per-target outcomes (attack actions)
             */
            items?: Array<{
                /**
                 * the target, as "(x,y)"
                 */
                label: string;
                ok: boolean;
                detail: Message;
            }>;
        }>;
    }>;
    /**
     * cities the run left out, e.g. all cities skips a city with no hero
     */
    skippedCities?: Array<FlowSkippedCity>;
};

export type FlowPreviewLog = {
    /**
     * when the preview ran
     */
    at: number;
    cities: Array<{
        cityId: number;
        cityName: string;
        /**
         * false: an action failed and everything the flow did in this city since the last wait was rolled back
         */
        ok: boolean;
        /**
         * the failure that rolled back this city's part of the run
         */
        error: Message | null;
        steps: Array<{
            action: Message;
            ok: boolean;
            /**
             * what happened, or why it failed
             */
            detail: Message;
            /**
             * the city could not do it right now (e.g. nothing affordable to train); the run carried on
             */
            skipped?: boolean;
            /**
             * per-target outcomes (attack actions)
             */
            items?: Array<{
                /**
                 * the target, as "(x,y)"
                 */
                label: string;
                ok: boolean;
                detail: Message;
            }>;
        }>;
    }>;
    skippedCities: Array<FlowSkippedCity>;
};

export type Flow = {
    id: string;
    name: string;
    actions: Array<FlowAction>;
    cities: 'all' | Array<number>;
    repeat: boolean;
    /**
     * 'queued': waits for the lord's active flow to finish its run (one flow runs at a time); 'waiting': paused on a wait action
     */
    status: 'idle' | 'queued' | 'running' | 'waiting';
    /**
     * index of the action the run continues with
     */
    nextAction: number;
    runs: number;
    /**
     * epoch milliseconds
     */
    queuedAt: number;
    /**
     * a queued repeat starts no earlier than this
     */
    notBefore: number;
    /**
     * while waiting: when the wait ends (or is checked again)
     */
    waitUntil: number;
    /**
     * while waiting: held before its next actions until every hero of its cities is home, since then (0 = not held)
     */
    heldSince: number;
    /**
     * why the flow stopped on its own (a failed run; repeat was switched off)
     */
    stopReason: Message | null;
    lastRun: FlowRunLog | null;
    /**
     * the latest preview, until the flow runs, is edited or repeat is switched
     */
    lastPreview: FlowPreviewLog | null;
};

export type FlowRunReport = {
    preview: boolean;
    /**
     * the flow after starting it (null for a preview)
     */
    flow: Flow | null;
    /**
     * what ran now, up to the first wait (empty when the flow was queued)
     */
    cities: Array<{
        cityId: number;
        cityName: string;
        /**
         * false: an action failed and everything the flow did in this city since the last wait was rolled back
         */
        ok: boolean;
        /**
         * the failure that rolled back this city's part of the run
         */
        error: Message | null;
        steps: Array<{
            action: Message;
            ok: boolean;
            /**
             * what happened, or why it failed
             */
            detail: Message;
            /**
             * the city could not do it right now (e.g. nothing affordable to train); the run carried on
             */
            skipped?: boolean;
            /**
             * per-target outcomes (attack actions)
             */
            items?: Array<{
                /**
                 * the target, as "(x,y)"
                 */
                label: string;
                ok: boolean;
                detail: Message;
            }>;
        }>;
    }>;
    /**
     * cities the run leaves out, e.g. all cities skips a city with no hero
     */
    skippedCities: Array<FlowSkippedCity>;
};

